import copy
import hashlib
import json
import runpy
from pathlib import Path

root = Path('.')
def snapshot():
    return {str(p): hashlib.sha256(p.read_bytes()).hexdigest()
            for p in root.rglob('*') if p.is_file() and '.git' not in p.parts}
before = snapshot()
release = json.loads(Path('ops/releases/current.json').read_text())
functions = {name: runpy.run_path(path)['options']
             for name, path in release['consumers'].items()}
expected = {'timeout_ms': 7500, 'attempts': 4}
evidence = {}
for step, phase in enumerate(release['phases'], 1):
    for consumer in phase['active']:
        key = (consumer, phase['config'])
        reused = key in evidence
        if not reused:
            config = json.loads(Path(phase['config']).read_text())
            original = copy.deepcopy(config)
            result = functions[consumer](config)
            evidence[key] = (result, config == original)
        result, unchanged = evidence[key]
        print(f\"step={step} phase={phase['name']"'!r} consumer={consumer} config={phase['"'config']} result={result} contract={'PASS' if result == expected else 'FAIL'} mapping_unchanged={unchanged} reused={reused}\")
print('Mitigation: restore bridge before rollback overlap; use existing bridge evidence:')
for consumer in ('new', 'old'):
    result, unchanged = evidence[(consumer, 'ops/config/bridge.json')]
    print(f'{consumer}: result={result} contract={result == expected} mapping_unchanged={unchanged}')
print(f'All supplied non-Git files unchanged; no scratch created: {before == snapshot()}')
PY"
